package com.paymesh.backend.security.auth;
import com.paymesh.backend.testing.BusinessJwtTestSupport;
import com.paymesh.backend.security.accounts.*;
import com.paymesh.backend.service.internal.InternalPaymentService;
import com.paymesh.backend.service.impl.CheckoutExecution;
import com.paymesh.backend.settlement.ReconciliationService;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.*;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.context.bean.override.mockito.*;
import org.springframework.test.web.servlet.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
@SpringBootTest @AutoConfigureMockMvc(print=MockMvcPrint.NONE)
class CheckoutIntegrationTest extends BusinessJwtTestSupport {
 @Autowired MockMvc mvc;@Autowired com.fasterxml.jackson.databind.ObjectMapper json;@Autowired CheckoutTransactions transactions;@Autowired CheckoutExecution execution;@Autowired ReconciliationService reconciliation;@Autowired InternalPaymentService core;
 @MockitoBean CheckoutDemoGate gate;@MockitoBean CheckoutRateLimit limiter;@MockitoSpyBean SecurityAuditEventRepository audits;@MockitoSpyBean com.paymesh.backend.gateway.RoutingPaymentGateway gateway;
 Identity owner,other;String merchant,token,linkId;
 @BeforeEach void setup()throws Exception{when(gate.enabled()).thenReturn(true);when(limiter.allow(anyString(),anyString(),anyBoolean())).thenReturn(true);merchant="checkout-"+UUID.randomUUID();owner=identity("MERCHANT",Set.of(merchant));other=identity("MERCHANT",Set.of("checkout-other-"+UUID.randomUUID()));var link=createLink("INR","UPI");token=link.get("checkoutPath").asText().substring("/checkout/".length());linkId=link.get("linkId").asText();}
 com.fasterxml.jackson.databind.JsonNode body(MvcResult r)throws Exception{return json.readTree(r.getResponse().getContentAsByteArray());}
 com.fasterxml.jackson.databind.JsonNode createLink(String currency,String method)throws Exception{return body(mvc.perform(post("/api/v1/merchant/payment-links").with(jwt(owner)).header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content(json.writeValueAsBytes(Map.of("amount","999999999999.99","currency",currency,"paymentMethod",method,"customerReference","order-test","description","<img src=x>","expiryHours",24)))).andReturn());}
 MvcResult read(String token)throws Exception{return mvc.perform(get("/api/v1/checkout/"+token)).andReturn();}
 MvcResult pay(String key,String outcome)throws Exception{var b=new HashMap<String,Object>();b.put("confirmed",true);if(outcome!=null)b.put("simulationOutcome",outcome);return submit(token,key,json.writeValueAsString(b));}
 MvcResult submit(String token,String key,String bytes)throws Exception{return mvc.perform(post("/api/v1/checkout/"+token+"/pay").header("Origin","http://127.0.0.1:5500").header("X-PayMesh-Checkout","1").header("Idempotency-Key",key).contentType("application/json").content(bytes)).andReturn();}
 long attempts(){return jdbc.queryForObject("SELECT count(*) FROM checkout_attempts WHERE link_id=?",Long.class,UUID.fromString(linkId));}
 UUID payment(){return jdbc.queryForObject("SELECT payment_id FROM checkout_attempts WHERE link_id=? ORDER BY created_at DESC LIMIT 1",UUID.class,UUID.fromString(linkId));}
 @Test void migrationsAndPublicReadAreSafeAndReadOnly()throws Exception{assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM flyway_schema_history WHERE version='13' AND success",Integer.class));long n=jdbc.queryForObject("SELECT count(*) FROM payments",Long.class);var r=read(token);assertEquals(200,r.getResponse().getStatus());var b=body(r);assertEquals("999999999999.99",b.get("amount").asText());assertEquals("ACTIVE",b.get("checkoutStatus").asText());assertTrue(b.get("merchantName").asText().contains("not recorded"));for(String f:List.of("merchantId","paymentId","userId","email","mobile","gatewayName","authorizationVersion","key_digest"))assertFalse(b.has(f));assertEquals(0,attempts());assertEquals(n,jdbc.queryForObject("SELECT count(*) FROM payments",Long.class));assertEquals("no-store",r.getResponse().getHeader("Cache-Control"));}
 @Test void malformedUnknownExpiredAndCancelled()throws Exception{assertEquals(400,read("bad").getResponse().getStatus());assertEquals(404,read("z".repeat(43)).getResponse().getStatus());jdbc.update("UPDATE payment_links SET created_at=now()-interval '2 hour',expires_at=now()-interval '1 hour' WHERE link_id=?",UUID.fromString(linkId));assertEquals("EXPIRED",body(read(token)).get("checkoutStatus").asText());assertEquals(409,pay("expired",null).getResponse().getStatus());jdbc.update("UPDATE payment_links SET status='CANCELLED' WHERE link_id=?",UUID.fromString(linkId));assertEquals("CANCELLED",body(read(token)).get("checkoutStatus").asText());assertEquals(409,pay("cancelled",null).getResponse().getStatus());}
 @Test void inactiveMerchantAndAmbiguousMembershipFailClosed()throws Exception{jdbc.update("UPDATE merchant_administration SET status='SUSPENDED' WHERE merchant_id=?",merchant);assertEquals("UNAVAILABLE",body(read(token)).get("checkoutStatus").asText());assertEquals(409,pay("off",null).getResponse().getStatus());jdbc.update("UPDATE merchant_administration SET status='ACTIVE' WHERE merchant_id=?",merchant);jdbc.update("UPDATE merchant_memberships SET active=false WHERE user_id=?",owner.userId());assertEquals(409,pay("off-2",null).getResponse().getStatus());}
 @Test void successReceiptAndNoSecondCharge()throws Exception{assertEquals(200,pay("once",null).getResponse().getStatus());assertEquals("PAID",body(read(token)).get("checkoutStatus").asText());assertEquals("SUCCESS",jdbc.queryForObject("SELECT status FROM payments WHERE payment_id=?",String.class,payment()));assertEquals(payment(),jdbc.queryForObject("SELECT payment_id FROM payment_links WHERE link_id=?",UUID.class,UUID.fromString(linkId)));assertEquals(200,pay("once",null).getResponse().getStatus());assertEquals(409,pay("different",null).getResponse().getStatus());assertEquals(1,attempts());var status=body(mvc.perform(get("/api/v1/checkout/"+token+"/status")).andReturn());assertNotNull(status.get("receiptReference"));assertFalse(status.get("canPay").asBoolean());assertTrue(status.get("paidAt").isTextual());}
 @Test void failureIsDefinitiveAndRetryRetainsHistory()throws Exception{assertEquals(200,pay("failed","FAILED").getResponse().getStatus());UUID first=payment();assertEquals("FAILED",body(read(token)).get("checkoutStatus").asText());assertEquals("FAILED",jdbc.queryForObject("SELECT status FROM payments WHERE payment_id=?",String.class,first));assertEquals(200,pay("failed","FAILED").getResponse().getStatus());assertEquals(1,attempts());assertEquals(200,pay("retry","SUCCESS").getResponse().getStatus());assertEquals(2,attempts());assertNotEquals(first,payment());assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM checkout_attempts WHERE link_id=? AND status='SUCCESS'",Integer.class,UUID.fromString(linkId)));}
 @Test void timeoutBlocksRetriesAndReconciliationSynchronizesLink()throws Exception{assertEquals(202,pay("timeout","TIMEOUT").getResponse().getStatus());assertEquals("UNCERTAIN",body(read(token)).get("checkoutStatus").asText());UUID id=payment();assertEquals("PROCESSING",jdbc.queryForObject("SELECT status FROM payments WHERE payment_id=?",String.class,id));assertEquals(409,pay("new-key",null).getResponse().getStatus());assertEquals(202,pay("timeout","TIMEOUT").getResponse().getStatus());assertEquals(1,attempts());when(gate.enabled()).thenReturn(false);assertEquals(202,pay("timeout","TIMEOUT").getResponse().getStatus());assertEquals(400,pay("new-disabled","TIMEOUT").getResponse().getStatus());assertEquals("RESOLVED",reconciliation.reconcile(id).status());assertEquals("PAID",body(read(token)).get("checkoutStatus").asText());assertEquals("SUCCESS",jdbc.queryForObject("SELECT status FROM checkout_attempts WHERE payment_id=?",String.class,id));}
 @Test void clientCannotOverrideFixedFieldsOrConfirmation()throws Exception{for(String f:List.of("amount","currency","merchantId","paymentMethod","gateway","status","paymentId"))assertEquals(400,submit(token,"override","{\"confirmed\":true,\""+f+"\":\"x\"}").getResponse().getStatus());for(String s:List.of("{}","{\"confirmed\":false}","{\"confirmed\":\"true\"}","{\"confirmed\":true,\"confirmed\":true}","{\"confirmed\":true}{}"))assertEquals(400,submit(token,"bad",s).getResponse().getStatus());assertEquals(0,attempts());}
 @Test void outcomeControlsFailClosedWhenDisabled()throws Exception{when(gate.enabled()).thenReturn(false);assertTrue(body(read(token)).get("simulationChoices").isEmpty());assertEquals(400,pay("no-control","SUCCESS").getResponse().getStatus());assertEquals(400,pay("no-control","FAILED").getResponse().getStatus());assertEquals(200,pay("normal",null).getResponse().getStatus());}
 @Test void originCsrfBodyAndRateLimits()throws Exception{var media=mvc.perform(post("/api/v1/checkout/"+token+"/pay").contentType("text/plain").content("invalid")).andReturn();assertEquals(415,media.getResponse().getStatus());assertFalse(media.getResponse().getContentAsString().contains(token));assertEquals(400,mvc.perform(get("/api/v1/checkout/"+token+"?x=1")).andReturn().getResponse().getStatus());assertEquals(403,mvc.perform(post("/api/v1/checkout/"+token+"/pay").contentType("application/json").content("{\"confirmed\":true}")).andReturn().getResponse().getStatus());assertEquals(413,submit(token,"big","x".repeat(4097)).getResponse().getStatus());when(limiter.allow(anyString(),anyString(),anyBoolean())).thenReturn(false);assertEquals(429,read(token).getResponse().getStatus());}
 @Test void usdCardUsesStoredValuesAndStripe()throws Exception{var link=createLink("USD","CARD");String t=link.get("checkoutPath").asText().substring(10);assertEquals(200,submit(t,"usd","{\"confirmed\":true}").getResponse().getStatus());var p=jdbc.queryForMap("SELECT p.* FROM payments p JOIN checkout_attempts a USING(payment_id) WHERE a.link_id=?",UUID.fromString(link.get("linkId").asText()));assertEquals("USD",p.get("currency"));assertEquals("CARD",p.get("payment_method"));assertEquals(merchant,p.get("merchant_id"));}
 @Test void concurrentDuplicateAndDifferentKeyNeverDoubleExecute()throws Exception{var pool=Executors.newFixedThreadPool(2);try{var a=pool.submit(()->pay("same",null));var b=pool.submit(()->pay("same",null));assertTrue(Set.of(200,202).contains(a.get().getResponse().getStatus()));assertTrue(Set.of(200,202).contains(b.get().getResponse().getStatus()));assertEquals(1,attempts());assertEquals(409,pay("not-same",null).getResponse().getStatus());}finally{pool.shutdownNow();}}
 @Test void acceptedAttemptSurvivesExpirySuspensionAndCannotCancel()throws Exception{var accepted=transactions.accept(token,"accepted",null);assertFalse(accepted.replay());assertEquals(409,mvc.perform(post("/api/v1/merchant/payment-links/"+linkId+"/cancel").with(jwt(owner))).andReturn().getResponse().getStatus());jdbc.update("UPDATE merchant_administration SET status='SUSPENDED' WHERE merchant_id=?",merchant);jdbc.update("UPDATE payment_links SET created_at=now()-interval '2 hour',expires_at=now()-interval '1 hour' WHERE link_id=?",UUID.fromString(linkId));core.updatePaymentStatus(accepted.payment().paymentId(),com.paymesh.backend.enums.PaymentStatus.SUCCESS);assertEquals("PAID",body(read(token)).get("checkoutStatus").asText());}
 @Test void acceptedCrashNeverReexecutesAndRemainsProcessing()throws Exception{var a=transactions.accept(token,"crash",null);assertNotNull(a.payment());assertEquals(202,pay("crash",null).getResponse().getStatus());assertEquals("PROCESSING",body(read(token)).get("checkoutStatus").asText());assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM payment_gateway_transactions WHERE payment_id=?",Integer.class,payment()));assertEquals(409,pay("replacement",null).getResponse().getStatus());}
 @Test void financialAuthorizationAndOwnershipRemainIntact()throws Exception{pay("secure",null);UUID id=payment();assertEquals(401,mvc.perform(post("/api/v1/payments/"+id+"/process")).andReturn().getResponse().getStatus());assertTrue(Set.of(403,404).contains(mvc.perform(get("/api/v1/payments/"+id).with(jwt(other))).andReturn().getResponse().getStatus()));assertEquals(200,mvc.perform(get("/api/v1/payments/"+id).with(jwt(owner))).andReturn().getResponse().getStatus());assertEquals(404,mvc.perform(get("/api/v1/merchant/payment-links/"+linkId).with(jwt(other))).andReturn().getResponse().getStatus());}
 @Test void acceptanceAuditFailureRollsBackPaymentAndAttempt()throws Exception{long before=jdbc.queryForObject("SELECT count(*) FROM payments",Long.class);doThrow(new IllegalStateException("test-only")).when(audits).saveAndFlush(argThat(e->e!=null&&e.getEventType().equals("CHECKOUT_ACCEPTED")));try{assertEquals(503,pay("rollback",null).getResponse().getStatus());assertEquals(0,attempts());assertEquals(before,jdbc.queryForObject("SELECT count(*) FROM payments",Long.class));}finally{reset(audits);}}
 @Test void changedSameKeyAndCrossLinkKeyAreScoped()throws Exception{pay("scoped","FAILED");assertEquals(409,pay("scoped","SUCCESS").getResponse().getStatus());var link=createLink("INR","CARD");assertEquals(200,submit(link.get("checkoutPath").asText().substring(10),"scoped","{\"confirmed\":true}").getResponse().getStatus());}
 @Test void cancellationRacesAcceptanceWithoutInterruptingAcceptedPayment()throws Exception{var pool=Executors.newFixedThreadPool(2);try{var a=pool.submit(()->pay("race",null));var b=pool.submit(()->mvc.perform(post("/api/v1/merchant/payment-links/"+linkId+"/cancel").with(jwt(owner))).andReturn());int paid=a.get().getResponse().getStatus(),cancelled=b.get().getResponse().getStatus();assertTrue(paid==200&&cancelled==409||paid==409&&cancelled==200);assertEquals(paid==200?1:0,attempts());}finally{pool.shutdownNow();}}
 @Test void gatewayRunsOutsideAccountLockAndSuspensionDoesNotEraseAcceptedAttempt()throws Exception{var entered=new CountDownLatch(1);var release=new CountDownLatch(1);var pool=Executors.newSingleThreadExecutor();doAnswer(inv->{entered.countDown();if(!release.await(15,TimeUnit.SECONDS))throw new IllegalStateException("test-only-timeout");return inv.callRealMethod();}).when(gateway).processPayment(any(UUID.class),any(java.math.BigDecimal.class),anyString());try{var pending=pool.submit(()->pay("in-flight",null));assertTrue(entered.await(15,TimeUnit.SECONDS));assertEquals(409,pay("another",null).getResponse().getStatus());var admin=identity("ADMIN",Set.of());var suspended=mvc.perform(post("/api/v1/admin/merchant/suspend").with(jwt(admin)).contentType("application/json").content(json.writeValueAsBytes(Map.of("merchantId",merchant,"reason","isolated concurrency test")))).andReturn();assertEquals(200,suspended.getResponse().getStatus());assertEquals("PROCESSING",body(read(token)).get("checkoutStatus").asText());release.countDown();assertEquals(200,pending.get().getResponse().getStatus());assertEquals("PAID",body(read(token)).get("checkoutStatus").asText());}finally{release.countDown();pool.shutdownNow();reset(gateway);}}
 @Test void existingRefundPathPreservesPaidReceiptAndOwnership()throws Exception{pay("refund-compatible",null);UUID id=payment();String paidAt=body(read(token)).get("paidAt").asText();var refunded=mvc.perform(post("/api/v1/payments/"+id+"/refund").with(jwt(owner)).header("Idempotency-Key","isolated-full-refund").contentType("application/json").content("{\"amount\":999999999999.99}")).andReturn();assertEquals(201,refunded.getResponse().getStatus());var r=body(read(token));assertEquals("PAID",r.get("checkoutStatus").asText());assertEquals("REFUNDED",r.get("paymentStatus").asText());assertEquals(paidAt,r.get("paidAt").asText());}

 @Test void unresolvedAttemptWinsEvenWhenFailedHistoryTimestampIsLater()throws Exception{pay("old-failure","FAILED");UUID failed=payment();transactions.accept(token,"accepted-next",null);jdbc.update("UPDATE checkout_attempts SET created_at=clock_timestamp()+interval '1 day' WHERE payment_id=?",failed);assertEquals("PROCESSING",body(read(token)).get("checkoutStatus").asText());var owned=body(mvc.perform(get("/api/v1/merchant/payment-links/"+linkId).with(jwt(owner))).andReturn());assertEquals("PROCESSING",owned.get("status").asText());assertEquals(409,mvc.perform(post("/api/v1/merchant/payment-links/"+linkId+"/cancel").with(jwt(owner))).andReturn().getResponse().getStatus());assertEquals(409,pay("replacement",null).getResponse().getStatus());}

}
